        postKey("/admin/coupons",Map.ofEntries(Map.entry("code","SAVE10"),Map.entry("title","Ten percent"),Map.entry("minimumAmount",100),Map.entry("discountPercent",10),Map.entry("maximumDiscount",100),Map.entry("maximumUses",1),Map.entry("effectiveFrom","2026-09-01T00:00:00Z"),Map.entry("effectiveUntil","2026-10-01T00:00:00Z"),Map.entry("active",true)),admin(),key()).andExpect(status().isCreated());
