    @Test void concurrentRedemptionsCannotSpendSamePointsTwice()throws Exception{
        rule("REDEMPTION",0);postKey("/admin/wallets/"+customerId()+"/adjust",Map.of("amount",0,"points",20,"reason","Reward grant"),admin(),key()).andExpect(status().isOk());
        var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);
        try{Callable<Integer> attempt=()->{barrier.await(10,TimeUnit.SECONDS);return postKey("/customer/rewards/redeem",Map.of("points",20),customer,key()).andReturn().getResponse().getStatus();};
            var a=pool.submit(attempt);var b=pool.submit(attempt);assertThat(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);
        }finally{pool.shutdownNow();}
        assertThat(jdbc.queryForObject("select balance from wallets",java.math.BigDecimal.class)).isEqualByComparingTo("20");
        assertThat(jdbc.queryForObject("select reward_points from wallets",Long.class)).isZero();
    }

